// 1. Create the Custom Exception Blueprint
class AgeViolationException extends Exception {
    public AgeViolationException(String message) {
        super(message); // Pass message up to the parent Exception class
    }
}

// 2. Use it in your business logic
public void registerUser(int age) throws AgeViolationException {
    if (age < 18) {
        throw new AgeViolationException("User must be 18 or older.");
    }
}
